module TopModule (
    input         clk,
    input         reset,
    output [2:0]  ena,
    output [15:0] q
);

    // Separate 4-bit registers for each BCD digit
    reg [3:0] ones, tens, hundreds, thousands;

    // Registered enable signals indicating when upper digits should increment
    reg ena_tens, ena_hundreds, ena_thousands;

    // Internal carry signals generated by lower digits
    wire carry_ones = (ones == 4'd9);
    wire carry_tens = (tens == 4'd9);
    wire carry_hundreds = (hundreds == 4'd9);

    // Output enable assignments reflect registered enables
    assign ena = {ena_thousands, ena_hundreds, ena_tens};

    // Concatenate output digits into 16-bit BCD output
    assign q = {thousands, hundreds, tens, ones};

    always @(posedge clk) begin
        if (reset) begin
            // Synchronously reset all digits and enables
            ones       <= 4'd0;
            tens       <= 4'd0;
            hundreds   <= 4'd0;
            thousands  <= 4'd0;

            ena_tens       <= 1'b0;
            ena_hundreds   <= 1'b0;
            ena_thousands  <= 1'b0;
        end else begin
            // Increment ones digit unconditionally
            if (carry_ones)
                ones <= 4'd0;
            else
                ones <= ones + 1'b1;

            // Update ena_tens based on carry_ones (carry from previous digit)
            ena_tens <= carry_ones;

            // Increment tens digit only if ena_tens was asserted in previous cycle
            if (ena_tens) begin
                if (carry_tens)
                    tens <= 4'd0;
                else
                    tens <= tens + 1'b1;
            end

            // Update ena_hundreds based on carry_tens and ena_tens (next digit enable)
            ena_hundreds <= ena_tens && carry_tens;

            // Increment hundreds digit only if ena_hundreds was asserted in previous cycle
            if (ena_hundreds) begin
                if (carry_hundreds)
                    hundreds <= 4'd0;
                else
                    hundreds <= hundreds + 1'b1;
            end

            // Update ena_thousands based on carry_hundreds and ena_hundreds
            ena_thousands <= ena_hundreds && carry_hundreds;

            // Increment thousands digit only if ena_thousands was asserted in previous cycle
            if (ena_thousands) begin
                // Wrap around to 0 after 9
                if (thousands == 4'd9)
                    thousands <= 4'd0;
                else
                    thousands <= thousands + 1'b1;
            end
        end
    end

endmodule